const visuals = {web:'<div class="code-viz">'+webDemo+'</div>',dashboard:dashboard(),science,workflow,code};
function renderProjects(filter='all'){
const shown=projects.map((p,i)=>({...p,index:i})).filter(p=>filter==='all'||p.category===filter);
document.querySelector('#projects').innerHTML=shown.map(p=>'<article class="project"><div class="project-visual" aria-hidden="true">'+(p.repo==='Calgary-Crime-Neural-Network-Data-Science-Project'?'<img class="project-image" src="calgary-analysis.png" alt="" loading="lazy">':p.repo==='Bank-Customer-Churn-Data-Science-Project'?'<img class="project-image" src="churn-analysis.png" alt="" loading="lazy">':visuals[p.visual])+'<span class="visual-label">'+(p.category==='science'?'PROJECT REPOSITORY · ORIGINAL CHART':'ILLUSTRATIVE PROJECT PREVIEW')+'</span></div><div class="project-heading"><h3>'+p.title+'</h3><span>'+p.categoryName+'</span></div><p>'+p.desc+'</p><div class="project-meta">'+p.tags.map(t=>'<span class="tag">'+t+'</span>').join('')+'<button class="details" data-project="'+p.index+'" aria-label="Read about '+p.title+'">Project details</button></div></article>').join('');
document.querySelector('#project-count').textContent=shown.length+' selected project'+(shown.length===1?'':'s');
}
renderProjects();
document.querySelector('.filters').addEventListener('click',e=>{const b=e.target.closest('button[data-filter]');if(!b)return;document.querySelectorAll('.filters button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});renderProjects(b.dataset.filter)});
let projectTrigger=null;
const dialog=document.querySelector('#project-dialog');
document.querySelector('#projects').addEventListener('click',e=>{const b=e.target.closest('[data-project]');if(!b)return;const p=projects[Number(b.dataset.project)];projectTrigger=b;document.querySelector('#dialog-content').innerHTML='<p class="eyebrow blue">'+p.categoryName+'</p><h2 id="dialog-title">'+p.title+'</h2><p>'+p.details+'</p><p><strong>Focus</strong><br>'+p.scope+'</p><div class="project-meta">'+p.tags.map(t=>'<span class="tag">'+t+'</span>').join('')+'</div><a class="button" href="https://github.com/yash-jain-98/'+p.repo+'" target="_blank" rel="noopener">View repository on GitHub</a>';dialog.showModal()});
document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
dialog.addEventListener('close',()=>projectTrigger?.focus());
document.querySelector('.lab-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(!b)return;document.querySelectorAll('.lab-tabs button').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});const modes={web:[webDemo,'Designed with care. Built to work.'],data:[dashboard('Make your data make sense'),'Better questions. Clearer answers.'],auto:[workflow,'Less busywork. More possibility.']};document.querySelector('#lab-view').innerHTML=modes[b.dataset.mode][0];document.querySelector('#lab-caption').textContent=modes[b.dataset.mode][1]});
document.querySelectorAll('[data-service]').forEach(a=>a.addEventListener('click',()=>{document.querySelector('#service').value=a.dataset.service}));
document.querySelector('#contact-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.reportValidity())return;const name=form.elements.name.value.trim(),service=form.elements.service.value,message=form.elements.message.value.trim();const body='Hi Yash,\n\nMy name is '+name+'. I’m interested in '+service.toLowerCase()+'.\n\n'+message+'\n\nBest,\n'+name;location.href='mailto:works.yashjain@gmail.com?subject='+encodeURIComponent('Project enquiry: '+service)+'&body='+encodeURIComponent(body)});
document.querySelector('.copy-email').addEventListener('click',async e=>{try{await navigator.clipboard.writeText('works.yashjain@gmail.com');e.target.textContent='Email copied';document.querySelector('#copy-status').textContent='Email address copied to clipboard.';setTimeout(()=>e.target.textContent='Copy email',2500)}catch{e.target.textContent='Select email above to copy';document.querySelector('#copy-status').textContent='Clipboard unavailable. Select and copy the email address above.'}});
document.querySelector('#year').textContent=new Date().getFullYear();

const serviceContent={web:{kicker:'WEBSITE DESIGN & DEVELOPMENT',title:'Give your business<br>a better front door.',description:'A considered website helps people understand what you do and makes the next step feel effortless. I design and develop responsive experiences around your business and your users.',items:['Business websites & landing pages','Mobile-first layouts & clear navigation','UI improvements & website redesigns'],cta:'Let’s talk websites',service:'Website design & development'},data:{kicker:'DATA ANALYTICS & DATA SCIENCE',title:'Make your data<br>worth more to you.',description:'Bring scattered information into focus. From interactive reports to exploratory analysis and machine-learning studies, I help turn data into something you can understand and use.',items:['Power BI & Excel dashboards','SQL analysis, cleaning & preparation','Exploratory analysis & ML models'],cta:'Let’s explore your data',service:'Data analytics & science'},auto:{kicker:'AUTOMATION & WORKFLOWS',title:'Give your time<br>back to better work.',description:'Repetitive tasks should not define your day. I build focused scripts and data workflows that make recurring processes easier to run and maintain.',items:['Python scripts & data processing','Web data collection workflows','Spreadsheet & reporting automation'],cta:'Let’s simplify your workflow',service:'Automation'}};
document.querySelector('.solution-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-mode]');if(!b)return;const s=serviceContent[b.dataset.mode];document.querySelector('#service-kicker').textContent=s.kicker;document.querySelector('#service-title').innerHTML=s.title;document.querySelector('#service-description').textContent=s.description;document.querySelector('#service-list').innerHTML=s.items.map(x=>'<li>'+x+'</li>').join('');const c=document.querySelector('#service-cta');c.textContent=s.cta;c.dataset.service=s.service});
